'use strict';
const Route={
 picking:false,preview:null,
 sanitize(saved){
  const normalize=nodes=>{for(const n of nodes||[])if(n.mode==='flyby'&&!Gravity.canFlyby(object(n.id)))n.mode='stop';};
  normalize(saved.itinerary);const f=saved.flight;
  if(f?.route?.length){const current=f.route[f.legIndex],changed=current?.mode==='flyby'&&!Gravity.canFlyby(object(current.id));normalize(f.route);
   if(changed){const covered=f.covered||0;f.from=Space.point(saved.ship.p3);f.distance=distance(f.from,object(f.target));f.covered=0;f.aim=null;f.encounter=null;f.coastRate=0;if(f.wind)f.wind.baseCovered-=covered;if(saved.phase==='flyby')saved.phase='cruise';}
  }
  return saved;
 },
 angleText(radians){const d=radians*180/Math.PI;return d!==0&&d<.01?d.toExponential(2).replace('.',',')+'°':fmt(d,2)+'°';},
 radiusText(m){return m<1e10?compact(m/1000)+' км':fmt(m/149597870700,3)+' а.е.';},
 isFlyby(f=state.flight){return !!f?.route?.length&&Gravity.canFlyby(object(f.target))&&f.route[f.legIndex]?.mode==='flyby'&&f.legIndex<f.route.length-1;},
 braking(){if(state.flight?.manualCoast)return false;return !!state.flight?.route?.length?!this.isFlyby():state.auto;},
 analyze(nodes=state.itinerary){
  let from=state.ship,fuel=state.matter,beta=0,valid=nodes.length>0,records=[],departure=object(state.current),usedStars=new Set(state.destroyed);
  for(let i=0;i<nodes.length;i++){
   const n=nodes[i],o=object(n.id),d=o?distance(from,o):0;let issue='';
   if(!o?.navigable||!from.p3||d<1e-12){issue='Нет физических координат или точка совпадает с предыдущей.';valid=false;}
   if(beta===0&&d>0){if(departure?.kind==='star'&&!usedStars.has(departure.id)){fuel=0;beta=Stellar.plan(Rocket.dryMass*1000,SAILS[state.sail].areaM2,0,Stellar.r0,Math.max(1,state.controlG||100),Stellar.pulseYears,SAILS[state.sail].targetBeta).beta;usedStars.add(departure.id);}else{const engine=Rocket.plan(fuel,d);beta=engine.beta;fuel=Math.max(0,fuel-engine.budget);if(beta===0){issue='Нет горючего для нового разгона.';valid=false;}}}
   const r={id:n.id,mode:n.mode,d,beta,issue};
   if(n.mode==='flyby'){
    const next=object(nodes[i+1]?.id);
    if(!Gravity.canFlyby(o)){r.issue='Гравитационный поворот доступен только у чёрной дыры.';valid=false;}
    else if(!next?.p3){r.issue='Пролёт требует следующей точки маршрута.';valid=false;}
    else{const angle=V3.angle(V3.sub(o.p3,from.p3),V3.sub(next.p3,o.p3)),sol=Gravity.solve(o.gravity,beta,angle);Object.assign(r,sol,{required:angle});if(!sol.ok){r.issue=sol.reason;valid=false;}else if(!sol.straight&&sol.rp*5>Math.min(d,distance(o,next))*.001*LY){r.issue='Область пролёта перекрывает соседнюю точку.';valid=false;}}
   }else if(beta>0){const stop=Magnetic.stopping(fuel,beta);fuel=Math.max(0,stop.magnetic.finalMass/1000-Rocket.dryMass-stop.engine.budget);beta=0;}
   records.push(r);if(o){from=o;departure=o;}
  }
  return{valid,records};
 },
 show(){
  const active=state.flight?.route?.length,nodes=active?state.flight.route:state.itinerary,analysis=active?null:this.analyze(nodes);this.preview=analysis;
  let html='<div class="modal-eyebrow">НАВИГАЦИЯ / 3D → 2D</div><h2>Маршрут.</h2><p>Звёзды — для разгона парусом, чёрные дыры — для поворотов без остановки. Последняя точка — остановка.</p>';
  if(!nodes.length)html+='<p class="route-empty">Добавьте первую точку из атласа. У промежуточной чёрной дыры можно выбрать гравитационный пролёт.</p>';
  html+='<ol class="route-list">'+nodes.map((n,i)=>{const o=object(n.id),r=analysis?.records[i];let detail=r?distanceText(r.d)+' · подлёт ≈ '+percentC(r.beta):i===state.flight.legIndex?'ТЕКУЩАЯ ТОЧКА':i<state.flight.legIndex?'ПРОЙДЕНА':'ВПЕРЕДИ';
   if(r&&i<nodes.length-1&&!Gravity.canFlyby(o))detail+=o.kind==='star'?'<br>После остановки — разгон парусом'+(state.destroyed.includes(o.id)?' недоступен: звезда уже использована.':'.'):'<br>Гравитационный поворот — только у чёрных дыр.';
   if(r&&n.mode==='flyby'){detail+='<br>Поворот в 3D: '+(r.required!==undefined?this.angleText(r.required):'—')+' · максимум '+(r.maxAngle!==undefined?this.angleText(Math.min(Math.PI,r.maxAngle)):'—');if(r.ok&&!r.straight)detail+='<br>Сближение: '+this.radiusText(r.rp);if(o.gravity?.assumed)detail+='<br>Масса и радиус — типовая модель, не измерение.';}
   return'<li class="route-node '+(r?.issue?'invalid':'')+'"><div class="route-node-name"><span>'+String(i+1).padStart(2,'0')+'</span><b>'+o.name+'</b></div><p>'+detail+(r?.issue?'<br><strong>'+r.issue+'</strong>':'')+'</p>'+(active?'<small>'+(n.mode==='flyby'?'ГРАВИТАЦИОННЫЙ ПРОЛЁТ':'ОСТАНОВКА')+'</small>':'<div class="route-node-actions"><button data-mode="'+i+'" '+(!Gravity.canFlyby(o)||i===nodes.length-1?'disabled':'')+'>'+(n.mode==='flyby'?'Пролёт ↝':'Остановка ■')+'</button><button data-up="'+i+'" aria-label="Поднять точку '+(i+1)+'" '+(i===0?'disabled':'')+'>↑</button><button data-down="'+i+'" aria-label="Опустить точку '+(i+1)+'" '+(i===nodes.length-1?'disabled':'')+'>↓</button><button data-remove="'+i+'" aria-label="Удалить точку '+(i+1)+'">×</button></div>')+'</li>';
  }).join('')+'</ol>';
  if(!active)html+='<div class="route-actions"><button class="map-size-action" id="addRoutePoint" '+(nodes.length>=12?'disabled':'')+'>Добавить точку из атласа +</button><button class="modal-start" id="startRoute" '+(!analysis.valid||state.flight?'disabled':'')+'>Начать маршрут →</button></div>';
  else html+='<p>Точка '+(state.flight.legIndex+1)+' из '+nodes.length+'. '+(state.phase==='flyby'?'Проходит гравитационный пролёт.':'Автопилот выполняет маршрут.')+'</p><button class="map-size-action" id="cancelRoute" '+(state.phase==='flyby'?'disabled':'')+'>Завершить маршрут на текущей точке</button>';
  html+='<p class="object-note">Остановка гасит скорость. У неиспользованной звезды следующий участок начинается со взрыва и разгона парусом выбранного размера; в остальных точках — на собственной тяге. Для поворота у чёрной дыры учитывается граница захвата. Прогноз уточняется при подлёте по фактической скорости. Вращение, приливное разрушение, нагрев и магнитосфера не моделируются. Неподвижный объект не даёт бесплатного прироста скорости.</p><button class="text-action" id="routeTheory">Как считаются углы и проекция ↗</button>';
  showDialog(html);
  $('dialogContent').onclick=e=>{const b=e.target.closest('button');if(!b||active)return;const d=b.dataset;let i;if(d.mode!==undefined){i=+d.mode;if(!Gravity.canFlyby(object(nodes[i].id))||i===nodes.length-1)return;nodes[i].mode=nodes[i].mode==='stop'?'flyby':'stop';}else if(d.up!==undefined){i=+d.up;[nodes[i-1],nodes[i]]=[nodes[i],nodes[i-1]];}else if(d.down!==undefined){i=+d.down;[nodes[i],nodes[i+1]]=[nodes[i+1],nodes[i]];}else if(d.remove!==undefined)nodes.splice(+d.remove,1);else return;if(nodes.length)nodes.at(-1).mode='stop';persist();this.show();};
  if(!active){$('addRoutePoint').onclick=()=>{this.picking=true;$('infoDialog').close();$('search').value='';openCatalog();toast('Выберите следующую точку маршрута.');};$('startRoute').onclick=()=>this.start();}
  else $('cancelRoute').onclick=()=>{this.abort();$('infoDialog').close();toast('Оставшиеся точки отменены. Автопилот остановится у текущей цели.');persist();};
  $('routeTheory').onclick=()=>showNavigationTheory();
 },
 add(id){if(state.itinerary.length>=12){toast('До 12 точек в одном маршруте.');return;}const o=object(id);if(!o?.navigable){toast('Для этого ориентира нет точных координат.');return;}if(state.itinerary.at(-1)?.id===id||(!state.itinerary.length&&state.current===id)){toast('Эта точка уже является началом текущего участка.');return;}state.itinerary.push({id,mode:'stop'});persist();},
 abort(){const f=state.flight;if(!f?.route?.length)return;f.route=null;state.auto=true;if(f.aim){const anchor=FlightView.ship();f.from={...state.ship,p3:[...state.ship.p3]};f.distance=distance(state.ship,object(f.target));f.covered=0;f.aim=null;f.encounter=null;f.view={a:anchor,b:MapLayout.project(object(f.target))};coastSetup();}},
 start(){syncClock();const check=this.analyze();if(!check.valid||state.flight)return;const nodes=state.itinerary.map(n=>({...n}));$('infoDialog').close();state.selected=nodes[0].id;launch();if(state.flight){state.flight.route=nodes;state.flight.legIndex=0;state.flight.encounter=null;this.configure();state.itinerary=[];log('Маршрут: '+nodes.map(n=>object(n.id).name+(n.mode==='flyby'?' [пролёт]':' [остановка]')).join(' → '));renderUI();persist();}},
 configure(){const f=state.flight;if(!this.isFlyby(f))return;const e=Gravity.encounter(f.from,object(f.target),object(f.route[f.legIndex+1].id),f.maxBeta);if(!e.ok)return;f.encounter={...e,beta:f.maxBeta};if(e.plan){delete f.view;f.aim=Space.point(V3.add(object(f.target).p3,e.plan.rows[0].offset));f.distance=distance(f.from,f.aim);}FlightMarks.plan(f);},
 prepare(f=state.flight){
  if(!this.isFlyby(f))return null;
  if(f.encounter&&Math.abs(f.encounter.beta-state.beta)<1e-12)return f.encounter;
  const body=object(f.target),next=object(f.route[f.legIndex+1].id),e=Gravity.encounter(f.from,body,next,state.beta);
  if(!e.ok){f.route[f.legIndex].mode='stop';f.encounter=null;f.aim=null;f.from=Space.point(state.ship.p3);f.distance=distance(f.from,body);f.covered=0;f.maxBeta=state.beta;delete f.view;FlightMarks.plan(f);toast('Пролёт недоступен на фактической скорости. Автопилот выполняет остановку.');log('Пролёт заменён остановкой: '+body.name+'. '+e.reason);return null;}
  f.encounter={...e,beta:state.beta};return f.encounter;
 },
 gate(f=state.flight){if(f.aim)return 0;const e=this.prepare(f);return e?.plan?Math.min(f.distance,e.plan.R/LY):0;},
 enter(){const f=state.flight,e=this.prepare(f);if(!e)return;if(e.straight){this.next(f,state.ship,state.beta);return;}state.phase='flyby';state.acceleration=0;f.encounter.plan.elapsedProper=0;f.encounter.lastEarth=0;f.encounter.lastProper=0;f.encounter.lastPath=0;log('Пролёт: '+object(f.target).name+'. Поворот '+this.angleText(e.angle)+', rₚ = '+this.radiusText(e.rp)+'.');},
 tick(dt){
  const f=state.flight,e=f.encounter,p=e.plan,body=object(f.target),old=p.elapsedProper||0,used=Math.min(dt,Math.max(0,p.proper-old));
  p.elapsedProper=old+used;const s=Gravity.atProper(p,p.elapsedProper);
  state.earth+=s.earth-e.lastEarth;state.proper+=s.proper-e.lastProper;state.totalDistance+=s.path-e.lastPath;e.lastEarth=s.earth;e.lastProper=s.proper;e.lastPath=s.path;
  state.ship=Space.point(V3.add(body.p3,s.offset));state.acceleration=0;state.beta=p.beta;
  if(p.elapsedProper>=p.proper){if(!state.visited.includes(body.id))state.visited.push(body.id);this.next(f,state.ship,p.beta);}return used;
 },
 next(old,from,beta){const nodes=old.route,index=old.legIndex+1,target=object(nodes[index]?.id);if(!target)return;state.selected=target.id;state.current=null;state.beta=beta;state.acceleration=0;state.phase='cruise';state.flight={view:{a:MapLayout.project(object(old.target)),b:MapLayout.project(target)},from:{...from,p3:[...from.p3]},target:target.id,fromId:old.target,distance:distance(from,target),covered:0,coastRate:0,maxBeta:beta,boost:false,engine:null,wind:null,magnetic:null,missed:false,autoStopping:false,route:nodes,legIndex:index,encounter:null};this.configure();FlightMarks.plan();coastSetup();renderUI();fitRoute(target);persist();},
 afterStop(old){if(!old.route?.length||old.legIndex>=old.route.length-1)return;const index=old.legIndex+1;state.selected=old.route[index].id;launch();if(state.flight){state.flight.route=old.route;state.flight.legIndex=index;state.flight.encounter=null;this.configure();persist();}},
 draw(){
  const f=state.flight,nodes=f?.route||state.itinerary;if(!nodes.length)return;let a=f?screen(f.from):screen(state.ship);const start=f?f.legIndex:0;
  for(let i=start;i<nodes.length;i++){const o=object(nodes[i].id),b=screen(o);drawPhysicalSegment(i===start?(f?f.from:state.ship):object(nodes[i-1].id),o,'#919191',.9,[3,5]);circle(b.x,b.y,18,'#999999',.7);text(String(i+1),b.x,b.y+3,8,'#555555','center');a=b;}
 },
 drawEncounter(){
  if(state.phase!=='flyby')return;const p=state.flight.encounter.plan,s=Gravity.atProper(p,p.elapsedProper||0),cx=width<700?width*.72:width*.48,cy=height*.30,scale=62/p.rp;
  // Explicit local diagram, independent of the interstellar map scale.
  ctx.save();ctx.beginPath();ctx.rect(cx-86,cy-86,172,172);ctx.clip();
  for(let i=1;i<p.rows.length;i++){const a=p.rows[i-1],b=p.rows[i];line(cx+Math.cos(a.phi)*a.r*scale,cy-Math.sin(a.phi)*a.r*scale,cx+Math.cos(b.phi)*b.r*scale,cy-Math.sin(b.phi)*b.r*scale,'#666666',1);}
  const rs=Gravity.rs(p.profile.massSolar);circle(cx,cy,Math.max(3,rs*scale),'#252525',1);circle(cx+Math.cos(s.phi)*s.r*scale,cy-Math.sin(s.phi)*s.r*scale,3,'#252525',2);ctx.restore();
  text('ЛОКАЛЬНАЯ ГЕОДЕЗИЧЕСКАЯ',cx,cy-96,7,'#777777','center');text('ОТДЕЛЬНЫЙ МАСШТАБ · 0 g',cx,cy+101,6,'#777777','center');
 },
 setup(){ $('routeBtn').onclick=()=>this.show();$('sourcesBtn').onclick=()=>showCatalogSources();}
};
function showCatalogSources(){showDialog('<div class="modal-eyebrow">АТЛАС / ИСТОЧНИКИ</div><h2>'+CATALOG_COUNTS.all+' реальных объектов.</h2><p>Исходные 42 точки дополнены выборками: 450 ближайших звёзд HYG 4.1, 80 галактик OpenNGC и 20 пульсаров ATNF 2.9.0. Повторы исходных объектов исключены. Это сохранённый срез каталогов, не запрос данных в реальном времени.</p><p><a href="https://github.com/astronexus/HYG-Database/tree/main/hyg" target="_blank" rel="noopener">HYG · David Nash / Astronexus</a>: направления J2000, параллактические расстояния, спектры, абсолютная V и светимость в V. Массы и радиусы в HYG отсутствуют.</p><p><a href="https://github.com/mattiaverga/OpenNGC" target="_blank" rel="noopener">OpenNGC · Mattia Verga и соавторы</a>: координаты, оптические оси, красное смещение, фотометрия. Для новых галактик 0,01 ≤ z ≤ 0,03 расстояния вычислены в плоской ΛCDM: H₀ = 70 км/с/Мпк, Ωm = 0,3, ΩΛ = 0,7. Это модельные оценки. Размеры используют угловое расстояние, светимость — luminosity distance; поглощение и K-коррекция не учтены.</p><p><a href="https://www.atnf.csiro.au/research/pulsar/psrcat/" target="_blank" rel="noopener">ATNF Pulsar Catalogue</a>: Manchester, Hobbs, Teoh & Hobbs (2005), AJ 129, 1993–2006. Выбраны независимые оценки DIST_A; пульсары доступны как точки остановки; гравитационные манёвры вокруг них выключены.</p><p>Первоначальные карточки: CDS/SIMBAD, NASA, ESO и научные статьи — индивидуальные ссылки в карточках. Координаты первоначальных объектов сверены по HYG, SIMBAD и ATNF.</p><p>Производные выборки HYG и OpenNGC распространяются по <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Преобразованы единицы, добавлены расчётные расстояния и русские пояснения.</p><p><a href="catalog-sources.json" target="_blank">Метаданные, контрольные суммы и формулы</a> · <a href="catalog-import.js" target="_blank">Производная выборка</a></p><button class="map-size-action" id="projectionInfo">Как устроена 2D-карта ↗</button>');$('projectionInfo').onclick=()=>showNavigationTheory();}
function showNavigationTheory(){showDialog('<div class="modal-eyebrow">НАВИГАЦИЯ / МОДЕЛЬ</div><h2>Поворот имеет предел.</h2><p>В игре гравитационные повороты доступны только у чёрных дыр, включая сверхмассивные. Пролёт — свободное падение в сферическом невращающемся поле Шварцшильда. Масса корабля мала по сравнению с телом. Скорость β = v∞/c относится к удалённому наблюдателю; у неподвижного объекта она одинакова до и после пролёта. Локально корабль ускоряется на подлёте и замедляется на вылете. Собственное ускорение равно 0 g.</p><div class="formula">rₛ = 2GM/c²; q = rₚ/rₛ<br>A = β²(q−1) / [1+β²(q−1)]<br>u = 1−t²<br>δ = 4∫₀¹ dt / √[A+(1−1/q)u−u²/q] − π</div><p>Это численный интеграл точного уравнения геодезической, а не ньютоновская формула на скорости света. На слабом поле δ ≈ (rₛ/b)(1+β⁻²). При 99% c для чёрной дыры на 10 rₛ: ≈ 12,84°, на 2 rₛ: ≈ 126,51°. При одинаковых β и rₚ/rₛ угол не зависит от массы дыры; физические расстояния и длительность пролёта растут пропорционально массе.</p><p>Минимум сближения — 1,001 критического радиуса захвата. Для заданного угла в 3D перицентр ищется численно, на ветви без дополнительных оборотов. Если угла не хватает — маршрут не запускается. Нагрев, приливы, магнитосфера, вращение и излучение окружения не моделируются; допустимость орбиты не означает выживаемость реального корабля.</p><p>Межзвёздные участки сшиваются по асимптотам у центров систем. Окрестность пролёта интегрируется отдельно до 1 000 rₚ и занимает не более 0,1% соседних участков; локальный чертёж имеет отдельный масштаб. Это приближение сшитых траекторий, а не общее решение многотельной задачи. Остановка означает условную стоянку в системе; посадка и выход на устойчивую орбиту отдельно не рассчитываются. Вблизи тела часы используют dt/dτ = γ∞/(1−rₛ/r); в остальном полёте — специальную теорию относительности.</p><h3>Как 3D становится 2D</h3><p>Раньше карта имела приблизительно реальные расстояния от Солнца и произвольно выбранные углы. Теперь для объектов с координатами используются прямое восхождение α, склонение δ и расстояние d:</p><div class="formula">Xeq = d cos δ cos α<br>Yeq = d cos δ sin α<br>Zeq = d sin δ<br>[Xg,Yg,Zg] = R · [Xeq,Yeq,Zeq]<br>Физические XYZ сохраняются<br>Схема: r = √(Xg²+Yg²+Zg²)<br>φ = atan2(−Yg,Xg) + Δφ<sub>t-SNE</sub></div><p>R — поворот ICRS → Galactic по соглашению IAU / ESA Gaia. Galactic XYZ — физические координаты, которые не меняются от раскладки. Для отображения используется ограниченный t-SNE: близость в 3D задаёт вероятности соседства, точки на Zg = 0 закреплены в XYg, радиус каждой точки на схеме равен её реальному расстоянию от Солнца. t-SNE оптимизирует только азимут с ограничением отклонения до 60° · |Zg|/d. Для разных диапазонов расстояний раскладка вычислена заранее и не прыгает при масштабировании. Это условная схема, не ортографическая проекция; экранные расстояния между произвольными объектами и экранные углы не равны физическим. Zg не теряется из расчётов: в карточках показана глубина, расстояния и углы маршрута считаются в полных трёх измерениях. Экранное пересечение линий не означает встречу, экранная длина не задаёт физическое расстояние.</p><p>Для сверхструктур без однозначных координат сохранены схематические ориентиры с подписью; они не допускаются в физические маршруты. Форма рукавов и поворот внешних галактик остаются условными чертежами. Космологическое расширение и движение объектов за время экспедиции не интегрируются.</p><p><a href="https://arxiv.org/html/1505.06481v2" target="_blank" rel="noopener">Уравнения релятивистского рассеяния</a> · <a href="https://gea.esac.esa.int/archive/documentation/GDR3/Data_processing/chap_cu3ast/sec_cu3ast_intro/ssec_cu3ast_intro_tansforms.html" target="_blank" rel="noopener">ESA Gaia: преобразование координат</a> · <a href="https://www.jmlr.org/papers/v9/vandermaaten08a.html" target="_blank" rel="noopener">t-SNE: исходная статья</a></p>');}
